-- ----------------------------------------------------------------------------
-- vw_assertions: Every claim in the ledger: definitions, theorems, finite verifications, hypotheses and falsified attempts.
-- Combines base table columns with calculated/lookup/aggregation fields.
-- ----------------------------------------------------------------------------
DROP VIEW IF EXISTS vw_assertions CASCADE;
CREATE VIEW vw_assertions WITH (security_invoker = ON) AS
SELECT
  t.assertion_id,                                                               -- AssertionId
  calc_assertions_name(t.assertion_id) AS name,                                 -- Name
  t.statement,                                                                  -- Statement
  t.reported_status,                                                            -- ReportedStatus
  t.proof_section,                                                              -- ProofSection
  t.kind,                                                                       -- Role of the claim in the research: Definition, Theorem, Known result, Finite check, Hypothesis, Bridge obligation or Prize problem.
  t.introduced_in_loop,                                                         -- The Effortless loop that added this claim; empty for claims carried over from research v05.
  calc_assertions_status_group(t.assertion_id) AS status_group,                 -- Proved (definition, proved, rederived known or Lean-verified), Checked (finite verification only), Falsified, Superseded or Open.
  calc_assertions_premise_count(t.assertion_id) AS premise_count,               -- Direct premises this claim depends on.
  calc_assertions_dependent_count(t.assertion_id) AS dependent_count,           -- Claims that list this one as a direct premise.
  calc_assertions_evidence_count(t.assertion_id) AS evidence_count,             -- Evidence files linked to this claim.
  calc_assertions_revision_count(t.assertion_id) AS revision_count,             -- Recorded status changes of this claim.
  calc_assertions_is_usable(t.assertion_id) AS is_usable,                       -- 1 when the claim may be used as a premise.
  calc_assertions_is_proof_eligible(t.assertion_id) AS is_proof_eligible,       -- 1 when the claim may be used in a proof (finite checks may not).
  calc_assertions_descendant_count(t.assertion_id) AS descendant_count,         -- Claims that rest on this one, directly or transitively.
  t.predicate,                                                                  -- The modeled predicate this claim is about, if any.
  calc_assertions_predicate_verdict(t.assertion_id) AS predicate_verdict,       -- The model's verdict on the predicate's bounded instances.
  calc_assertions_predicate_is_finitely_decidable(t.assertion_id) AS predicate_is_finitely_decidable,-- 1 when the model can decide the full statement.
  calc_assertions_is_model_linked(t.assertion_id) AS is_model_linked,           -- 1 when the claim is tied to a modeled predicate.
  calc_assertions_predicate_is_refuted(t.assertion_id) AS predicate_is_refuted, -- 1 when a counterexample instance fails in the model.
  calc_assertions_predicate_is_verified(t.assertion_id) AS predicate_is_verified,-- 1 when the model decides the statement true.
  calc_assertions_effective_status(t.assertion_id) AS effective_status,         -- The status the ledger uses: FALSIFIED when the model holds a counterexample; LEAN_VERIFIED when the Lean kernel accepts a proof of the claim (or confirms a kit result); OPEN for a reported Lean result the check here does not confirm; FINITE_VERIFIED when the model decides an open or checked claim true; otherwise the reported status.
  calc_assertions_is_model_decided(t.assertion_id) AS is_model_decided,         -- 1 when the model, not a report, decides the status.
  calc_assertions_is_model_contradicted(t.assertion_id) AS is_model_contradicted,-- 1 when the report asserts the claim (proved, Lean-verified, checked or definitional) and the model refutes it: the report is wrong. An OPEN claim the model refutes is decided, not contradicted.
  calc_assertions_model_verdict(t.assertion_id) AS model_verdict,               -- The model's verdict on the claim's predicate; NOT MODELED for a claim stated only in words.
  t.is_cached,                                                                  -- 1 when the *Cache fields of this row hold the last fresh compile (filled by loop_tools.build, cleared by every save).
  t.is_model_linked_cache,                                                      -- Cached IsModelLinked from the last fresh compile; read by IsModelLinked while IsCached = 1.
  t.model_verdict_cache,                                                        -- Cached ModelVerdict from the last fresh compile; read by ModelVerdict while IsCached = 1.
  t.effective_status_cache,                                                     -- Cached EffectiveStatus from the last fresh compile; read by EffectiveStatus while IsCached = 1.
  t.is_model_decided_cache,                                                     -- Cached IsModelDecided from the last fresh compile; read by IsModelDecided while IsCached = 1.
  t.is_model_contradicted_cache,                                                -- Cached IsModelContradicted from the last fresh compile; read by IsModelContradicted while IsCached = 1.
  t.status_group_cache,                                                         -- Cached StatusGroup from the last fresh compile; read by StatusGroup while IsCached = 1.
  t.is_usable_cache,                                                            -- Cached IsUsable from the last fresh compile; read by IsUsable while IsCached = 1.
  t.is_proof_eligible_cache,                                                    -- Cached IsProofEligible from the last fresh compile; read by IsProofEligible while IsCached = 1.
  t.source,                                                                     -- Where a claim comes from: kit for the kit's results; empty for this ledger's own claims.
  t.lean_module,                                                                -- For a kit result: its module.
  t.lean_declaration,                                                           -- The Lean declaration that states the claim: a prize problem's official statement, a kit case's headline theorem.
  calc_assertions_lean_statement(t.assertion_id) AS lean_statement,             -- The claim's statement in Lean, written by the build from its term tree (empty while some operator has no Lean meaning).
  calc_assertions_is_lean_expressible(t.assertion_id) AS is_lean_expressible,   -- 1 when the build writes the statement in Lean.
  calc_assertions_lean_check_count(t.assertion_id) AS lean_check_count,         -- Kernel checks of the current Lean statement.
  calc_assertions_lean_check_ok(t.assertion_id) AS lean_check_ok,               -- Kernel checks of the current Lean statement that passed.
  calc_assertions_is_officially_aligned(t.assertion_id) AS is_officially_aligned,-- 1 when Lean proves the claim's statement equivalent to the official one.
  calc_assertions_is_kit_module_linked(t.assertion_id) AS is_kit_module_linked, -- 1 when the claim is a kit module.
  calc_assertions_is_kit_declaration_linked(t.assertion_id) AS is_kit_declaration_linked,-- 1 when a Lean declaration states the claim.
  calc_assertions_lean_module_is_verified(t.assertion_id) AS lean_module_is_verified,-- 1 when the kit module is verified.
  calc_assertions_lean_declaration_is_verified(t.assertion_id) AS lean_declaration_is_verified,-- 1 when the Lean declaration is a verified theorem.
  calc_assertions_lean_module_url(t.assertion_id) AS lean_module_url,           -- The kit module's file.
  calc_assertions_is_own_claim(t.assertion_id) AS is_own_claim,                 -- 1 for this ledger's own claims, 0 for the kit's.
  calc_assertions_is_lean_linked(t.assertion_id) AS is_lean_linked,             -- 1 when the claim has a Lean form: its own Lean statement, a kit module or a Lean declaration.
  calc_assertions_is_formally_stated(t.assertion_id) AS is_formally_stated,     -- 1 when the claim is stated formally: as a term tree of the model or in Lean.
  calc_assertions_is_lean_verified(t.assertion_id) AS is_lean_verified,         -- 1 when the kernel accepted a proof of the claim's current Lean statement here, or the claim is a kit result reported proved and its module (or theorem) is verified here.
  calc_assertions_kit_link_count(t.assertion_id) AS kit_link_count,             -- Kit declarations linked to this claim.
  calc_assertions_kit_cover_count(t.assertion_id) AS kit_cover_count,           -- Verified kit theorems that state this claim or more.
  calc_assertions_kit_contradiction_count(t.assertion_id) AS kit_contradiction_count,-- Verified kit theorems that refute this claim. Must be 0 for a claim we hold.
  calc_assertions_kit_joint_count(t.assertion_id) AS kit_joint_count,           -- Kit theorems whose conjunction is this claim.
  calc_assertions_kit_joint_verified_count(t.assertion_id) AS kit_joint_verified_count,-- Of those, the verified ones.
  calc_assertions_kit_glue_proof_count(t.assertion_id) AS kit_glue_proof_count, -- Lean proofs of this claim that only restate kit theorems.
  calc_assertions_is_known_in_kit(t.assertion_id) AS is_known_in_kit,           -- 1 when the kit already proves this claim (a verified kit theorem says it or more, the jointly linked ones are all verified, or its Lean proof only restates the kit): not new against the catalog.
  calc_assertions_is_kit_contradicted(t.assertion_id) AS is_kit_contradicted,   -- 1 when a verified kit theorem refutes a claim the ledger holds (usable). A falsified claim the kit also refutes is agreement, not contradiction.
  calc_assertions_is_lean_contradicted(t.assertion_id) AS is_lean_contradicted, -- 1 when Lean proves a claim the model or the ledger refutes. Must be 0.
  calc_assertions_is_lean_unconfirmed(t.assertion_id) AS is_lean_unconfirmed,   -- 1 when a source reports the claim proved in Lean and the check here does not confirm it. Must be 0.
  calc_assertions_proof_basis(t.assertion_id) AS proof_basis,                   -- What the status rests on: the Lean kernel, the model, or a report.
  calc_assertions_on_current_path(t.assertion_id) AS on_current_path,           -- 1 when the claim is a step of the plan in force.
  calc_assertions_loop_target_count(t.assertion_id) AS loop_target_count,       -- Loops (planned, running or done) linked to this claim.
  calc_assertions_lean_declaration_url(t.assertion_id) AS lean_declaration_url  -- Where the Lean declaration is: read its statement there.
FROM assertions t;

-- ----------------------------------------------------------------------------
-- vw_dependencies: Declared one-step logical dependencies between assertions.
-- Combines base table columns with calculated/lookup/aggregation fields.
-- ----------------------------------------------------------------------------
DROP VIEW IF EXISTS vw_dependencies CASCADE;
CREATE VIEW vw_dependencies WITH (security_invoker = ON) AS
SELECT
  t.dependency_id,                                                              -- DependencyId
  calc_dependencies_name(t.dependency_id) AS name,                              -- Name
  t.conclusion,                                                                 -- The assertion that depends on the premise.
  t.premise                                                                     -- The assertion the conclusion relies on.
FROM dependencies t;

-- ----------------------------------------------------------------------------
-- vw_prerequisites: Transitive closure of Dependencies, one row per (conclusion, ancestor), regenerated by research/loop_tools.py.
-- Combines base table columns with calculated/lookup/aggregation fields.
-- ----------------------------------------------------------------------------
DROP VIEW IF EXISTS vw_prerequisites CASCADE;
CREATE VIEW vw_prerequisites WITH (security_invoker = ON) AS
SELECT
  t.prerequisite_id,                                                            -- PrerequisiteId
  calc_prerequisites_name(t.prerequisite_id) AS name,                           -- Name
  t.conclusion_key,                                                             -- The assessment this transitive premise feeds.
  t.premise,                                                                    -- A transitive ancestor of the conclusion (including itself).
  calc_prerequisites_premise_usable(t.prerequisite_id) AS premise_usable,       -- PremiseUsable
  calc_prerequisites_premise_proof_eligible(t.prerequisite_id) AS premise_proof_eligible,-- PremiseProofEligible
  calc_prerequisites_blocked(t.prerequisite_id) AS blocked,                     -- Blocked
  calc_prerequisites_proof_blocked(t.prerequisite_id) AS proof_blocked,         -- ProofBlocked
  calc_prerequisites_is_self(t.prerequisite_id) AS is_self,                     -- 1 for the row pairing a claim with itself.
  calc_prerequisites_is_blocking_ancestor(t.prerequisite_id) AS is_blocking_ancestor-- 1 when this ancestor is not usable and so blocks the conclusion.
FROM prerequisites t;

-- ----------------------------------------------------------------------------
-- vw_assessments: Compiled status of each assertion given the status of all its ancestors.
-- Combines base table columns with calculated/lookup/aggregation fields.
-- ----------------------------------------------------------------------------
DROP VIEW IF EXISTS vw_assessments CASCADE;
CREATE VIEW vw_assessments WITH (security_invoker = ON) AS
SELECT
  t.assessment_id,                                                              -- AssessmentId
  calc_assessments_name(t.assessment_id) AS name,                               -- Name
  t.assertion,                                                                  -- The assertion being assessed.
  calc_assessments_reported_status(t.assessment_id) AS reported_status,         -- ReportedStatus
  calc_assessments_statement(t.assessment_id) AS statement,                     -- The claim being assessed, in words.
  calc_assessments_kind(t.assessment_id) AS kind,                               -- Role of the claim (see Assertions.Kind).
  calc_assessments_status_group(t.assessment_id) AS status_group,               -- Proved, Checked, Falsified, Superseded or Open, from the reported status.
  calc_assessments_self_usable(t.assessment_id) AS self_usable,                 -- 1 when the claim itself is usable as a premise.
  calc_assessments_blocked_count(t.assessment_id) AS blocked_count,             -- BlockedCount
  calc_assessments_proof_blocked_count(t.assessment_id) AS proof_blocked_count, -- ProofBlockedCount
  calc_assessments_current_status(t.assessment_id) AS current_status,           -- BLOCKED when an ancestor is not usable, otherwise the effective status.
  calc_assessments_proof_eligible(t.assessment_id) AS proof_eligible,           -- ProofEligible
  calc_assessments_support_count(t.assessment_id) AS support_count,             -- Number of evidence files linked to this assertion.
  calc_assessments_evidence_gap(t.assessment_id) AS evidence_gap,               -- 1 for a reported finite verification with no evidence file; a model-decided one is its own evidence.
  calc_assessments_ancestor_blocked_count(t.assessment_id) AS ancestor_blocked_count,-- Ancestors (not counting the claim itself) that are not usable.
  calc_assessments_is_at_risk(t.assessment_id) AS is_at_risk,                   -- 1 when a claim reported as established rests on an ancestor that is open, falsified or superseded. Should always be 0.
  calc_assessments_ancestor_count(t.assessment_id) AS ancestor_count,           -- Claims this one rests on, directly or transitively.
  t.project_key,                                                                -- Dashboard this assessment rolls up to.
  calc_assessments_effective_status(t.assessment_id) AS effective_status,       -- The status the ledger uses (model-decided where it can be).
  calc_assessments_is_model_decided(t.assessment_id) AS is_model_decided        -- 1 when the model decides the status.
FROM assessments t;

-- ----------------------------------------------------------------------------
-- vw_evidence: Files produced by experiments, with sha256 hashes computed from disk.
-- Combines base table columns with calculated/lookup/aggregation fields.
-- ----------------------------------------------------------------------------
DROP VIEW IF EXISTS vw_evidence CASCADE;
CREATE VIEW vw_evidence WITH (security_invoker = ON) AS
SELECT
  t.evidence_id,                                                                -- EvidenceId
  calc_evidence_name(t.evidence_id) AS name,                                    -- Name
  t.path,                                                                       -- Path
  t.sha256,                                                                     -- Sha256
  calc_evidence_claim_count(t.evidence_id) AS claim_count,                      -- Cell values this evidence file claims.
  calc_evidence_claim_mismatch_count(t.evidence_id) AS claim_mismatch_count     -- Claimed values the model computes differently. Must be 0.
FROM evidence t;

-- ----------------------------------------------------------------------------
-- vw_revisions: Every status change, with the prior status kept visible.
-- Combines base table columns with calculated/lookup/aggregation fields.
-- ----------------------------------------------------------------------------
DROP VIEW IF EXISTS vw_revisions CASCADE;
CREATE VIEW vw_revisions WITH (security_invoker = ON) AS
SELECT
  t.revision_id,                                                                -- RevisionId
  calc_revisions_name(t.revision_id) AS name,                                   -- Name
  t.assertion,                                                                  -- The assertion whose status changed.
  t.prior_status,                                                               -- PriorStatus
  t.new_status,                                                                 -- NewStatus
  t.reason,                                                                     -- Reason
  t.replacement,                                                                -- Claim that replaces a falsified one, if any.
  t.loop                                                                        -- The Effortless loop that made this change; empty for v05 revisions recorded before native loops.
FROM revisions t;

-- ----------------------------------------------------------------------------
-- vw_loops: Research loops. Only Kind EFFORTLESS + State VERIFIED rows carry build receipts and hashes.
-- Combines base table columns with calculated/lookup/aggregation fields.
-- ----------------------------------------------------------------------------
DROP VIEW IF EXISTS vw_loops CASCADE;
CREATE VIEW vw_loops WITH (security_invoker = ON) AS
SELECT
  t.loop_id,                                                                    -- LoopId
  calc_loops_name(t.loop_id) AS name,                                           -- Name
  t.kind,                                                                       -- Kind
  t.state,                                                                      -- State
  t.build_receipt,                                                              -- BuildReceipt
  t.input_hash,                                                                 -- InputHash
  t.output_hash,                                                                -- OutputHash
  t.sequence,                                                                   -- Order of the loop across legacy and native loops (legacy 1-13, then native).
  t.started_at,                                                                 -- ISO time the loop started; recorded from the native loops after effortless-5.
  t.finished_at,                                                                -- ISO time the loop was verified.
  calc_loops_claims_added(t.loop_id) AS claims_added,                           -- Claims this loop added.
  calc_loops_revisions_made(t.loop_id) AS revisions_made,                       -- Status changes this loop recorded.
  calc_loops_falsifications_made(t.loop_id) AS falsifications_made,             -- Hypotheses this loop falsified.
  calc_loops_proofs_made(t.loop_id) AS proofs_made,                             -- Claims this loop moved to proved.
  t.project_key,                                                                -- Dashboard this loop rolls up to.
  t.hypothesis,                                                                 -- The hypothesis this loop tested, as stated before the experiment.
  t.summary,                                                                    -- What the loop changed in the hub and what the build showed.
  t.plan,                                                                       -- For a planned loop: what it will do and how its outcome will be read.
  calc_loops_target_count(t.loop_id) AS target_count                            -- Claims linked to this loop.
FROM loops t;

-- ----------------------------------------------------------------------------
-- vw_dashboards: Project-level rollups.
-- Combines base table columns with calculated/lookup/aggregation fields.
-- ----------------------------------------------------------------------------
DROP VIEW IF EXISTS vw_dashboards CASCADE;
CREATE VIEW vw_dashboards WITH (security_invoker = ON) AS
SELECT
  t.dashboard_id,                                                               -- DashboardId
  calc_dashboards_name(t.dashboard_id) AS name,                                 -- Name
  calc_dashboards_claim_count(t.dashboard_id) AS claim_count,                   -- ClaimCount
  calc_dashboards_blocked_count(t.dashboard_id) AS blocked_count,               -- BlockedCount
  calc_dashboards_completed_native_loops(t.dashboard_id) AS completed_native_loops,-- CompletedNativeLoops
  calc_dashboards_evidence_gap_count(t.dashboard_id) AS evidence_gap_count,     -- Finite-verified claims with no linked evidence.
  calc_dashboards_proved_count(t.dashboard_id) AS proved_count,                 -- Claims proved, rederived or definitional.
  calc_dashboards_checked_count(t.dashboard_id) AS checked_count,               -- Claims verified by finite computation only.
  calc_dashboards_falsified_count(t.dashboard_id) AS falsified_count,           -- Hypotheses shown false.
  calc_dashboards_open_count(t.dashboard_id) AS open_count,                     -- Claims still open.
  calc_dashboards_at_risk_count(t.dashboard_id) AS at_risk_count,               -- Established claims resting on something not established. Should be 0.
  calc_dashboards_open_prize_problem_count(t.dashboard_id) AS open_prize_problem_count,-- Prize problems not yet resolved.
  calc_dashboards_running_loop_count(t.dashboard_id) AS running_loop_count,     -- Loops in progress right now.
  calc_dashboards_legacy_loop_count(t.dashboard_id) AS legacy_loop_count,       -- Research cycles from v05, before native builds.
  calc_dashboards_conformance_mismatch_count(t.dashboard_id) AS conformance_mismatch_count,-- Optimizer claims the model disagrees with. Must be 0.
  calc_dashboards_predicates_failing_an_instance(t.dashboard_id) AS predicates_failing_an_instance,-- Predicates with at least one failing bounded instance.
  calc_dashboards_model_linked_claim_count(t.dashboard_id) AS model_linked_claim_count,-- Claims tied to a modeled predicate.
  calc_dashboards_model_decided_claim_count(t.dashboard_id) AS model_decided_claim_count,-- Claims whose status the model decides.
  calc_dashboards_model_contradiction_count(t.dashboard_id) AS model_contradiction_count,-- Claims the model refutes although their report does not. Must be 0.
  calc_dashboards_unmodeled_claim_count(t.dashboard_id) AS unmodeled_claim_count,-- Claims still only stated in words (no term tree, no Lean form).
  calc_dashboards_own_claim_count(t.dashboard_id) AS own_claim_count,           -- This ledger's own claims.
  calc_dashboards_kit_claim_count(t.dashboard_id) AS kit_claim_count,           -- Claims from the kit: its modules, its cases and its open statements.
  calc_dashboards_lean_verified_count(t.dashboard_id) AS lean_verified_count,   -- Claims the Lean kernel verifies.
  calc_dashboards_own_lean_verified_count(t.dashboard_id) AS own_lean_verified_count,-- Our claims with a kernel-checked Lean proof.
  calc_dashboards_own_lean_expressible_count(t.dashboard_id) AS own_lean_expressible_count,-- Our claims the build writes in Lean.
  calc_dashboards_own_known_in_kit_count(t.dashboard_id) AS own_known_in_kit_count,-- Our claims the kit already proves.
  calc_dashboards_kit_module_count(t.dashboard_id) AS kit_module_count,         -- Kit modules synced.
  calc_dashboards_kit_declaration_count(t.dashboard_id) AS kit_declaration_count,-- Lean declarations in the model (kit and submissions).
  calc_dashboards_kit_unverified_module_count(t.dashboard_id) AS kit_unverified_module_count,-- Modules with a declaration on a non-standard axiom. Must be 0.
  calc_dashboards_submission_count(t.dashboard_id) AS submission_count,         -- Public submissions.
  calc_dashboards_submission_lean_verified_count(t.dashboard_id) AS submission_lean_verified_count,-- Submissions the verifier accepted.
  calc_dashboards_submission_disagreement_count(t.dashboard_id) AS submission_disagreement_count,-- Submissions where our check and the verifier disagree (often a different kit commit).
  calc_dashboards_lean_contradiction_count(t.dashboard_id) AS lean_contradiction_count,-- Claims Lean proves although the model or the ledger refutes them. Must be 0.
  calc_dashboards_lean_unconfirmed_count(t.dashboard_id) AS lean_unconfirmed_count,-- Reported Lean results the check here does not confirm. Must be 0.
  calc_dashboards_kit_contradiction_count(t.dashboard_id) AS kit_contradiction_count,-- Claims we hold that a verified kit theorem refutes. Must be 0.
  calc_dashboards_kit_agreement_count(t.dashboard_id) AS kit_agreement_count,   -- Claims we falsified that a kit theorem refutes too.
  calc_dashboards_official_alignment_count(t.dashboard_id) AS official_alignment_count,-- Prize problems whose formal statement Lean proves equivalent to the official one.
  calc_dashboards_planned_loop_count(t.dashboard_id) AS planned_loop_count      -- Loops planned but not started.
FROM dashboards t;

-- ----------------------------------------------------------------------------
-- vw_evidence_links: Which evidence file supports which assertion. One row per (evidence, assertion) pair.
-- Combines base table columns with calculated/lookup/aggregation fields.
-- ----------------------------------------------------------------------------
DROP VIEW IF EXISTS vw_evidence_links CASCADE;
CREATE VIEW vw_evidence_links WITH (security_invoker = ON) AS
SELECT
  t.evidence_link_id,                                                           -- EvidenceId-AssertionId.
  calc_evidence_links_name(t.evidence_link_id) AS name,                         -- Display alias.
  t.evidence,                                                                   -- The evidence file.
  t.assertion,                                                                  -- The assertion it supports.
  calc_evidence_links_evidence_path(t.evidence_link_id) AS evidence_path        -- Repo-relative path of the evidence file.
FROM evidence_links t;

-- ----------------------------------------------------------------------------
-- vw_strategies: The plan toward a prize problem: where things stand, the route, and where the next loop aims. One row is in force (IsCurrent = 1); older plans are history.
-- Combines base table columns with calculated/lookup/aggregation fields.
-- ----------------------------------------------------------------------------
DROP VIEW IF EXISTS vw_strategies CASCADE;
CREATE VIEW vw_strategies WITH (security_invoker = ON) AS
SELECT
  t.strategy_id,                                                                -- after-loop-<n>: the plan as it stood after that loop.
  calc_strategies_name(t.strategy_id) AS name,                                  -- Display alias.
  t.goal,                                                                       -- The prize problem this plan aims at.
  t.is_current,                                                                 -- 1 on the plan in force now, 0 on history.
  t.headline,                                                                   -- Where things stand, in one sentence.
  t.approach,                                                                   -- The route being taken and why, in a short paragraph.
  t.missing,                                                                    -- What the route still lacks.
  t.next_target,                                                                -- The open claim the next loop serves.
  t.next_hypothesis,                                                            -- Where the next loop is aiming: its hypothesis in words.
  t.estimate,                                                                   -- An honest estimate of the odds, with what each number is for.
  t.updated_in_loop,                                                            -- The loop after which this plan was written.
  t.next_loop,                                                                  -- The planned loop (State PLANNED) that carries out the next step.
  t.project_key,                                                                -- Dashboard this plan rolls up to.
  calc_strategies_goal_statement(t.strategy_id) AS goal_statement,              -- The goal's statement.
  calc_strategies_goal_status_group(t.strategy_id) AS goal_status_group,        -- The goal's status group.
  calc_strategies_goal_ancestor_blocked_count(t.strategy_id) AS goal_ancestor_blocked_count,-- Open claims the goal waits on.
  calc_strategies_next_target_statement(t.strategy_id) AS next_target_statement,-- The next target's statement.
  calc_strategies_next_target_status_group(t.strategy_id) AS next_target_status_group,-- The next target's status group.
  calc_strategies_updated_in_loop_state(t.strategy_id) AS updated_in_loop_state,-- State of the loop that last updated the plan.
  calc_strategies_next_loop_state(t.strategy_id) AS next_loop_state,            -- PLANNED until the loop starts, then RUNNING and VERIFIED.
  calc_strategies_step_count(t.strategy_id) AS step_count,                      -- Claims on the route.
  calc_strategies_open_step_count(t.strategy_id) AS open_step_count,            -- Steps still open.
  calc_strategies_established_step_count(t.strategy_id) AS established_step_count,-- Steps proved or finitely checked.
  calc_strategies_blocking_step_count(t.strategy_id) AS blocking_step_count,    -- Steps that are open claims the goal waits on.
  calc_strategies_ruled_out_count(t.strategy_id) AS ruled_out_count             -- Mechanisms on the record as ruled out.
FROM strategies t;

-- ----------------------------------------------------------------------------
-- vw_strategy_steps: The claims on a plan's route, in order from the goal, each with its role and a note. Statuses are looked up from the claims.
-- Combines base table columns with calculated/lookup/aggregation fields.
-- ----------------------------------------------------------------------------
DROP VIEW IF EXISTS vw_strategy_steps CASCADE;
CREATE VIEW vw_strategy_steps WITH (security_invoker = ON) AS
SELECT
  t.strategy_step_id,                                                           -- <strategy>-<sequence>.
  calc_strategy_steps_name(t.strategy_step_id) AS name,                         -- Display alias.
  t.strategy,                                                                   -- The plan.
  t.assertion,                                                                  -- The claim at this step.
  t.sequence,                                                                   -- Order on the route, the goal first.
  t.role,                                                                       -- Goal, Reduction, Open obligation, Evidence or Ruled out.
  t.note,                                                                       -- Why this claim is on the route, in one line.
  calc_strategy_steps_statement(t.strategy_step_id) AS statement,               -- The claim.
  calc_strategy_steps_kind(t.strategy_step_id) AS kind,                         -- Kind of claim.
  calc_strategy_steps_status_group(t.strategy_step_id) AS status_group,         -- Proved, Checked, Open, Falsified or Superseded.
  calc_strategy_steps_effective_status(t.strategy_step_id) AS effective_status, -- The status the ledger uses.
  calc_strategy_steps_current_status(t.strategy_step_id) AS current_status,     -- Compiled status: BLOCKED when an ancestor is not usable.
  calc_strategy_steps_strategy_goal(t.strategy_step_id) AS strategy_goal,       -- The plan's goal.
  calc_strategy_steps_strategy_is_current(t.strategy_step_id) AS strategy_is_current,-- 1 when the plan is in force.
  calc_strategy_steps_goal_prerequisite_key(t.strategy_step_id) AS goal_prerequisite_key,-- Key of the Prerequisites row linking the goal to this claim.
  calc_strategy_steps_is_blocking_ancestor_of_goal(t.strategy_step_id) AS is_blocking_ancestor_of_goal,-- 1 when this claim is an unusable ancestor of the goal.
  calc_strategy_steps_is_open(t.strategy_step_id) AS is_open,                   -- 1 while the claim is open.
  calc_strategy_steps_is_established(t.strategy_step_id) AS is_established,     -- 1 when proved or finitely checked.
  calc_strategy_steps_blocks_goal(t.strategy_step_id) AS blocks_goal            -- 1 when this open claim is one the goal waits on.
FROM strategy_steps t;

-- ----------------------------------------------------------------------------
-- vw_loop_targets: The claims a loop serves, tests or builds on, so a loop page (planned, running or done) links to them.
-- Combines base table columns with calculated/lookup/aggregation fields.
-- ----------------------------------------------------------------------------
DROP VIEW IF EXISTS vw_loop_targets CASCADE;
CREATE VIEW vw_loop_targets WITH (security_invoker = ON) AS
SELECT
  t.loop_target_id,                                                             -- <loop>-<assertion>.
  calc_loop_targets_name(t.loop_target_id) AS name,                             -- Display alias.
  t.loop,                                                                       -- The loop.
  t.assertion,                                                                  -- A claim the loop serves, tests or builds on.
  t.role,                                                                       -- Serves (the open claim it advances), Tests (the hypothesis it decides), Builds on (results it uses) or Rules out.
  t.note,                                                                       -- How the loop relates to the claim, in one line.
  calc_loop_targets_statement(t.loop_target_id) AS statement,                   -- The claim.
  calc_loop_targets_kind(t.loop_target_id) AS kind,                             -- Kind of claim.
  calc_loop_targets_status_group(t.loop_target_id) AS status_group,             -- Proved, Checked, Open, Falsified or Superseded.
  calc_loop_targets_loop_state(t.loop_target_id) AS loop_state                  -- State of the loop.
FROM loop_targets t;

-- ----------------------------------------------------------------------------
-- vw_cell_states: The two states a cell can hold, with their colors. Problem 2 asks whether each occurs equally often.
-- Combines base table columns with calculated/lookup/aggregation fields.
-- ----------------------------------------------------------------------------
DROP VIEW IF EXISTS vw_cell_states CASCADE;
CREATE VIEW vw_cell_states WITH (security_invoker = ON) AS
SELECT
  t.cell_state_id,                                                              -- The color: white or black.
  calc_cell_states_name(t.cell_state_id) AS name,                               -- Display alias.
  t.state_value                                                                 -- The numeric value: white 0, black 1.
FROM cell_states t;

-- ----------------------------------------------------------------------------
-- vw_rules: Elementary cellular-automaton rules, as data. Rule 30 and the rest of its equivalence class (mirror 86, complement 135, both 149); each rule's table, symmetries and permutivity are computed from its RuleTableEntries.
-- Combines base table columns with calculated/lookup/aggregation fields.
-- ----------------------------------------------------------------------------
DROP VIEW IF EXISTS vw_rules CASCADE;
CREATE VIEW vw_rules WITH (security_invoker = ON) AS
SELECT
  t.rule_id,                                                                    -- rule-<number>.
  calc_rules_name(t.rule_id) AS name,                                           -- Display alias.
  t.rule_number,                                                                -- Wolfram rule number 0..255: the output for neighborhood n is bit n.
  calc_rules_table_number(t.rule_id) AS table_number,                           -- The rule number read back from the 8 computed transitions; equals RuleNumber when the table is consistent.
  calc_rules_black_output_count(t.rule_id) AS black_output_count,               -- How many of the 8 neighborhoods output black.
  calc_rules_is_balanced(t.rule_id) AS is_balanced,                             -- 1 when exactly half the neighborhoods output black (a precondition for density 1/2 heuristics).
  calc_rules_zero_neighborhood_output(t.rule_id) AS zero_neighborhood_output,   -- Output for the all-white neighborhood 000.
  calc_rules_is_quiescent(t.rule_id) AS is_quiescent,                           -- 1 when 000 stays white, so a white background stays white and the light cone is exact.
  calc_rules_mirror_rule_number(t.rule_id) AS mirror_rule_number,               -- The rule with left and right swapped (30 -> 86).
  calc_rules_complement_rule_number(t.rule_id) AS complement_rule_number,       -- The rule with black and white swapped in inputs and output (30 -> 135).
  calc_rules_is_mirror_symmetric(t.rule_id) AS is_mirror_symmetric,             -- 1 when the rule is its own mirror.
  calc_rules_polynomial_mismatch_count(t.rule_id) AS polynomial_mismatch_count, -- Neighborhoods where the rule differs from Mod[p + q + r + q r, 2].
  calc_rules_is_rule30_polynomial(t.rule_id) AS is_rule30_polynomial,           -- 1 when the rule is exactly Wolfram's polynomial form of Rule 30.
  calc_rules_left_insensitive_count(t.rule_id) AS left_insensitive_count,       -- Pairs of neighborhoods differing only in the left cell that give the same output.
  calc_rules_is_left_permutive(t.rule_id) AS is_left_permutive,                 -- 1 when flipping the left neighbor always flips the output (Rule 30: new = left XOR f(center, right)).
  calc_rules_right_insensitive_count(t.rule_id) AS right_insensitive_count,     -- Pairs of neighborhoods differing only in the right cell that give the same output.
  calc_rules_is_right_permutive(t.rule_id) AS is_right_permutive,               -- 1 when flipping the right neighbor always flips the output.
  calc_rules_run_count(t.rule_id) AS run_count                                  -- Runs evolving under this rule.
FROM rules t;

-- ----------------------------------------------------------------------------
-- vw_neighborhoods: The 8 neighborhoods a new cell is computed from: the cell and its immediate neighbors (left, center, right). Index = left*4 + center*2 + right selects the bit of the rule number.
-- Combines base table columns with calculated/lookup/aggregation fields.
-- ----------------------------------------------------------------------------
DROP VIEW IF EXISTS vw_neighborhoods CASCADE;
CREATE VIEW vw_neighborhoods WITH (security_invoker = ON) AS
SELECT
  t.neighborhood_id,                                                            -- n<left><center><right>.
  calc_neighborhoods_name(t.neighborhood_id) AS name,                           -- Display alias.
  t.left_state,                                                                 -- The left neighbor (p).
  t.center_state,                                                               -- The cell itself (q).
  t.right_state,                                                                -- The right neighbor (r).
  calc_neighborhoods_neighborhood_index(t.neighborhood_id) AS neighborhood_index,-- left*4 + center*2 + right.
  calc_neighborhoods_mirror_index(t.neighborhood_id) AS mirror_index,           -- Index of the left-right reflected neighborhood.
  calc_neighborhoods_complement_index(t.neighborhood_id) AS complement_index,   -- Index of the color-swapped neighborhood.
  calc_neighborhoods_polynomial_value(t.neighborhood_id) AS polynomial_value,   -- Wolfram's Rule 30 polynomial Mod[p + q + r + q r, 2] at this neighborhood.
  calc_neighborhoods_entry_count(t.neighborhood_id) AS entry_count              -- Rule tables that list this neighborhood.
FROM neighborhoods t;

-- ----------------------------------------------------------------------------
-- vw_rule_table_entries: One transition of one rule: neighborhood -> output value. The rule table is computed from the rule number; symmetries and permutivity are read off the table.
-- Combines base table columns with calculated/lookup/aggregation fields.
-- ----------------------------------------------------------------------------
-- ----------------------------------------------------------------------------
-- vw_rule_table_entries: One transition of one rule: neighborhood -> output value. The rule table is computed from the rule number; symmetries and permutivity are read off the table.
-- SELF-REFERENTIAL SETTLE: RuleTableEntries has lookup field(s) reading a computed
-- column of its own table through a self-FK. Settled level-by-level (seeds first,
-- then each row once its drivers are settled) via a jsonb accumulator carried
-- through ONE recursive self-reference. No cache: re-settles on every read.
-- Settle targets: output_value. Drivers: left_partner, right_partner.
-- ----------------------------------------------------------------------------
DROP VIEW IF EXISTS vw_rule_table_entries CASCADE;
CREATE VIEW vw_rule_table_entries WITH (security_invoker = ON) AS
WITH RECURSIVE acc AS (
  SELECT 1 AS step,
    COALESCE((SELECT jsonb_object_agg(t.rule_table_entry_id, jsonb_build_object(
      'output_value', MOD((FLOOR(((COALESCE((SELECT CASE WHEN v::text ~ '^-?[0-9]*\.?[0-9]+$' THEN v::numeric ELSE NULL END FROM (SELECT ((SELECT rule_number::integer FROM rules WHERE rule_id = (SELECT NULLIF(t.rule::text,'')))) AS v OFFSET 0) __safe_numeric), 0) / NULLIF(COALESCE((SELECT CASE WHEN v::text ~ '^-?[0-9]*\.?[0-9]+$' THEN v::numeric ELSE NULL END FROM (SELECT (POWER((2)::NUMERIC, ((SELECT calc_neighborhoods_neighborhood_index(neighborhood_id)::integer FROM neighborhoods WHERE neighborhood_id = (SELECT NULLIF(t.neighborhood::text,''))))::NUMERIC)) AS v OFFSET 0) __safe_numeric), 0), 0)))::NUMERIC)::BIGINT)::NUMERIC, (2)::NUMERIC)
    ))
    FROM rule_table_entries t WHERE NULLIF(t.left_partner,'') IS NULL AND NULLIF(t.right_partner,'') IS NULL), '{}'::jsonb) AS settled
  UNION ALL
  SELECT a.step + 1, a.settled || COALESCE((
    SELECT jsonb_object_agg(t.rule_table_entry_id, jsonb_build_object(
      'output_value', MOD((FLOOR(((COALESCE((SELECT CASE WHEN v::text ~ '^-?[0-9]*\.?[0-9]+$' THEN v::numeric ELSE NULL END FROM (SELECT ((SELECT rule_number::integer FROM rules WHERE rule_id = (SELECT NULLIF(t.rule::text,'')))) AS v OFFSET 0) __safe_numeric), 0) / NULLIF(COALESCE((SELECT CASE WHEN v::text ~ '^-?[0-9]*\.?[0-9]+$' THEN v::numeric ELSE NULL END FROM (SELECT (POWER((2)::NUMERIC, ((SELECT calc_neighborhoods_neighborhood_index(neighborhood_id)::integer FROM neighborhoods WHERE neighborhood_id = (SELECT NULLIF(t.neighborhood::text,''))))::NUMERIC)) AS v OFFSET 0) __safe_numeric), 0), 0)))::NUMERIC)::BIGINT)::NUMERIC, (2)::NUMERIC)
    ))
    FROM rule_table_entries t
    WHERE NOT (a.settled ? t.rule_table_entry_id) AND NOT (NULLIF(t.left_partner,'') IS NULL AND NULLIF(t.right_partner,'') IS NULL) AND (NULLIF(t.left_partner,'') IS NULL OR a.settled ? t.left_partner) AND (NULLIF(t.right_partner,'') IS NULL OR a.settled ? t.right_partner)
  ), '{}'::jsonb)
  FROM acc a
  WHERE EXISTS (SELECT 1 FROM rule_table_entries t
    WHERE NOT (a.settled ? t.rule_table_entry_id) AND NOT (NULLIF(t.left_partner,'') IS NULL AND NULLIF(t.right_partner,'') IS NULL) AND (NULLIF(t.left_partner,'') IS NULL OR a.settled ? t.left_partner) AND (NULLIF(t.right_partner,'') IS NULL OR a.settled ? t.right_partner))
),
settled AS (SELECT s.settled FROM acc s ORDER BY s.step DESC LIMIT 1)
SELECT
  t.rule_table_entry_id,                                                        -- <rule>-n<pattern>.
  calc_rule_table_entries_name(t.rule_table_entry_id) AS name,                  -- Display alias.
  t.rule,                                                                       -- The rule this transition belongs to.
  t.neighborhood,                                                               -- The input neighborhood.
  t.left_partner,                                                               -- Set when the left cell is white: the same rule with the left cell black. (One direction only, so the row graph stays acyclic.)
  t.right_partner,                                                              -- Set when the right cell is white: the same rule with the right cell black.
  calc_rule_table_entries_left_state(t.rule_table_entry_id) AS left_state,      -- The left cell of the neighborhood.
  calc_rule_table_entries_right_state(t.rule_table_entry_id) AS right_state,    -- The right cell of the neighborhood.
  calc_rule_table_entries_rule_number(t.rule_table_entry_id) AS rule_number,    -- The rule number.
  calc_rule_table_entries_neighborhood_index(t.rule_table_entry_id) AS neighborhood_index,-- Which bit of the rule number this is.
  calc_rule_table_entries_mirror_index(t.rule_table_entry_id) AS mirror_index,  -- Index of the mirrored neighborhood.
  calc_rule_table_entries_complement_index(t.rule_table_entry_id) AS complement_index,-- Index of the complemented neighborhood.
  calc_rule_table_entries_polynomial_value(t.rule_table_entry_id) AS polynomial_value,-- The Rule 30 polynomial at this neighborhood.
  (SELECT settled #>> ARRAY[t.rule_table_entry_id::text, 'output_value'] FROM settled)::integer AS output_value,-- The new cell state: bit NeighborhoodIndex of the rule number.
  calc_rule_table_entries_weight(t.rule_table_entry_id) AS weight,              -- This transition's contribution to the rule number.
  calc_rule_table_entries_mirror_weight(t.rule_table_entry_id) AS mirror_weight,-- This transition's contribution to the mirror rule's number.
  calc_rule_table_entries_complement_weight(t.rule_table_entry_id) AS complement_weight,-- This transition's contribution to the complement rule's number.
  calc_rule_table_entries_matches_polynomial(t.rule_table_entry_id) AS matches_polynomial,-- 1 when the output equals Mod[p + q + r + q r, 2].
  (SELECT settled #>> ARRAY[NULLIF(t.left_partner,''), 'output_value'] FROM settled)::integer AS left_partner_output,-- Output with the left cell flipped.
  calc_rule_table_entries_is_left_sensitive(t.rule_table_entry_id) AS is_left_sensitive,-- On rows with a left partner: 1 when flipping the left cell flips the output.
  (SELECT settled #>> ARRAY[NULLIF(t.right_partner,''), 'output_value'] FROM settled)::integer AS right_partner_output,-- Output with the right cell flipped.
  calc_rule_table_entries_is_right_sensitive(t.rule_table_entry_id) AS is_right_sensitive,-- On rows with a right partner: 1 when flipping the right cell flips the output.
  calc_rule_table_entries_use_count(t.rule_table_entry_id) AS use_count,        -- How many cells of the runs were produced by this transition.
  t.is_cached,                                                                  -- 1 when the *Cache fields of this row hold the last fresh compile (filled by loop_tools.build, cleared by every save).
  t.matches_polynomial_cache                                                    -- Cached MatchesPolynomial from the last fresh compile; read by MatchesPolynomial while IsCached = 1.
FROM rule_table_entries t;

-- ----------------------------------------------------------------------------
-- vw_initial_conditions: The states of all cells at time 0: a background color plus the listed seed cells.
-- Combines base table columns with calculated/lookup/aggregation fields.
-- ----------------------------------------------------------------------------
DROP VIEW IF EXISTS vw_initial_conditions CASCADE;
CREATE VIEW vw_initial_conditions WITH (security_invoker = ON) AS
SELECT
  t.initial_condition_id,                                                       -- Name of the initial condition.
  calc_initial_conditions_name(t.initial_condition_id) AS name,                 -- Display alias.
  t.background,                                                                 -- The state of every cell not listed as a seed cell.
  calc_initial_conditions_background_value(t.initial_condition_id) AS background_value,-- Numeric background state.
  calc_initial_conditions_seed_cell_count(t.initial_condition_id) AS seed_cell_count,-- Explicitly listed cells.
  calc_initial_conditions_black_seed_count(t.initial_condition_id) AS black_seed_count,-- Listed cells that are black.
  calc_initial_conditions_origin_seed_count(t.initial_condition_id) AS origin_seed_count,-- Listed cells at position 0.
  calc_initial_conditions_is_single_seed(t.initial_condition_id) AS is_single_seed-- 1 for the prize problems' initial condition: one nonzero cell (black) at position 0 on white.
FROM initial_conditions t;

-- ----------------------------------------------------------------------------
-- vw_seed_cells: A cell of an initial condition that differs from (or is stated beside) the background.
-- Combines base table columns with calculated/lookup/aggregation fields.
-- ----------------------------------------------------------------------------
DROP VIEW IF EXISTS vw_seed_cells CASCADE;
CREATE VIEW vw_seed_cells WITH (security_invoker = ON) AS
SELECT
  t.seed_cell_id,                                                               -- <initial condition>-p<position>.
  calc_seed_cells_name(t.seed_cell_id) AS name,                                 -- Display alias.
  t.initial_condition,                                                          -- The initial condition this cell belongs to.
  t.position,                                                                   -- Position i of the seed cell.
  t.state,                                                                      -- Its state.
  calc_seed_cells_state_value(t.seed_cell_id) AS state_value                    -- Numeric state.
FROM seed_cells t;

-- ----------------------------------------------------------------------------
-- vw_runs: One evolution: a rule applied to an initial condition up to a depth. The prize problems are about the run of Rule 30 from the single seed.
-- Combines base table columns with calculated/lookup/aggregation fields.
-- ----------------------------------------------------------------------------
DROP VIEW IF EXISTS vw_runs CASCADE;
CREATE VIEW vw_runs WITH (security_invoker = ON) AS
SELECT
  t.run_id,                                                                     -- Name of the run.
  calc_runs_name(t.run_id) AS name,                                             -- Display alias.
  t.rule,                                                                       -- The rule applied at every time step.
  t.initial_condition,                                                          -- The states at time 0.
  t.depth,                                                                      -- The last time step computed: the horizon.
  calc_runs_rule_number(t.run_id) AS rule_number,                               -- The rule number.
  calc_runs_is_quiescent(t.run_id) AS is_quiescent,                             -- 1 when 000 -> white.
  calc_runs_background_value(t.run_id) AS background_value,                     -- The background state.
  calc_runs_is_single_seed(t.run_id) AS is_single_seed,                         -- 1 for the single seed.
  calc_runs_is_light_cone_exact(t.run_id) AS is_light_cone_exact,               -- 1 when every cell outside |i| <= t is white, so computing only the cone is exact.
  calc_runs_is_prize_setup(t.run_id) AS is_prize_setup,                         -- 1 for the prize problems' setup: Rule 30 from the single seed.
  calc_runs_cell_count(t.run_id) AS cell_count,                                 -- Cells computed (the light cone).
  calc_runs_black_cell_count(t.run_id) AS black_cell_count,                     -- Black cells in the cone.
  calc_runs_line_count(t.run_id) AS line_count,                                 -- Time steps computed.
  calc_runs_total_cell_updates(t.run_id) AS total_cell_updates,                 -- Cell updates needed to reach the depth.
  calc_runs_center_length(t.run_id) AS center_length,                           -- Terms of the center column computed: c(0) .. c(Depth).
  calc_runs_center_ones(t.run_id) AS center_ones,                               -- Black terms in the center column.
  calc_runs_center_density(t.run_id) AS center_density,                         -- Share of black in the computed center column.
  calc_runs_center_discrepancy(t.run_id) AS center_discrepancy,                 -- Ones minus zeros in the computed center column.
  calc_runs_max_abs_center_discrepancy(t.run_id) AS max_abs_center_discrepancy, -- Largest |ones - zeros| over all center prefixes.
  calc_runs_longest_center_run(t.run_id) AS longest_center_run,                 -- Longest constant run in the center column.
  calc_runs_center_run_bound_violations(t.run_id) AS center_run_bound_violations,-- Center cells past the Theorem D bound for their run. Must be 0.
  t.is_cached,                                                                  -- 1 when the *Cache fields of this row hold the last fresh compile (filled by loop_tools.build, cleared by every save).
  t.is_light_cone_exact_cache,                                                  -- Cached IsLightConeExact from the last fresh compile; read by IsLightConeExact while IsCached = 1.
  t.is_prize_setup_cache                                                        -- Cached IsPrizeSetup from the last fresh compile; read by IsPrizeSetup while IsCached = 1.
FROM runs t;

-- ----------------------------------------------------------------------------
-- vw_time_steps: One line of a run: time step t. Width, black count and the center term are aggregated from its cells; cell updates accumulate along the time chain.
-- Combines base table columns with calculated/lookup/aggregation fields.
-- ----------------------------------------------------------------------------
-- ----------------------------------------------------------------------------
-- vw_time_steps: One line of a run: time step t. Width, black count and the center term are aggregated from its cells; cell updates accumulate along the time chain.
-- SELF-REFERENTIAL SETTLE: TimeSteps has lookup field(s) reading a computed
-- column of its own table through a self-FK. Settled level-by-level (seeds first,
-- then each row once its drivers are settled) via a jsonb accumulator carried
-- through ONE recursive self-reference. No cache: re-settles on every read.
-- Settle targets: cumulative_cell_updates. Drivers: previous_step.
-- ----------------------------------------------------------------------------
DROP VIEW IF EXISTS vw_time_steps CASCADE;
CREATE VIEW vw_time_steps WITH (security_invoker = ON) AS
WITH RECURSIVE acc AS (
  SELECT 1 AS step,
    COALESCE((SELECT jsonb_object_agg(t.time_step_id, jsonb_build_object(
      'cumulative_cell_updates', CASE WHEN COALESCE(((SELECT (NULLIF(t.time::text,''))::integer))::NUMERIC, 0) = 0 THEN (0)::text ELSE ((COALESCE((SELECT CASE WHEN v::text ~ '^-?[0-9]*\.?[0-9]+$' THEN v::numeric ELSE NULL END FROM (SELECT ((SELECT jsonb_extract_path_text('{}'::jsonb, NULLIF(t.previous_step,''), 'cumulative_cell_updates'))) AS v OFFSET 0) __safe_numeric), 0) + COALESCE((SELECT CASE WHEN v::text ~ '^-?[0-9]*\.?[0-9]+$' THEN v::numeric ELSE NULL END FROM (SELECT (CASE WHEN COALESCE(((SELECT (NULLIF(t.time::text,''))::integer))::NUMERIC, 0) = 0 THEN (0)::text ELSE ((COALESCE((SELECT CASE WHEN v::text ~ '^-?[0-9]*\.?[0-9]+$' THEN v::numeric ELSE NULL END FROM (SELECT ((COALESCE(2, 0) * COALESCE((SELECT CASE WHEN v::text ~ '^-?[0-9]*\.?[0-9]+$' THEN v::numeric ELSE NULL END FROM (SELECT ((SELECT (NULLIF(t.time::text,''))::integer)) AS v OFFSET 0) __safe_numeric), 0))) AS v OFFSET 0) __safe_numeric), 0) + COALESCE(1, 0)))::text END) AS v OFFSET 0) __safe_numeric), 0)))::text END
    ))
