    SELECT jsonb_object_agg(t.time_step_id, jsonb_build_object(
      'cumulative_cell_updates', CASE WHEN COALESCE(((SELECT (NULLIF(t.time::text,''))::integer))::NUMERIC, 0) = 0 THEN (0)::text ELSE ((COALESCE((SELECT CASE WHEN v::text ~ '^-?[0-9]*\.?[0-9]+$' THEN v::numeric ELSE NULL END FROM (SELECT ((SELECT jsonb_extract_path_text(a.settled, NULLIF(t.previous_step,''), 'cumulative_cell_updates'))) AS v OFFSET 0) __safe_numeric), 0) + COALESCE((SELECT CASE WHEN v::text ~ '^-?[0-9]*\.?[0-9]+$' THEN v::numeric ELSE NULL END FROM (SELECT (CASE WHEN COALESCE(((SELECT (NULLIF(t.time::text,''))::integer))::NUMERIC, 0) = 0 THEN (0)::text ELSE ((COALESCE((SELECT CASE WHEN v::text ~ '^-?[0-9]*\.?[0-9]+$' THEN v::numeric ELSE NULL END FROM (SELECT ((COALESCE(2, 0) * COALESCE((SELECT CASE WHEN v::text ~ '^-?[0-9]*\.?[0-9]+$' THEN v::numeric ELSE NULL END FROM (SELECT ((SELECT (NULLIF(t.time::text,''))::integer)) AS v OFFSET 0) __safe_numeric), 0))) AS v OFFSET 0) __safe_numeric), 0) + COALESCE(1, 0)))::text END) AS v OFFSET 0) __safe_numeric), 0)))::text END
