settled AS (SELECT s.settled FROM acc s ORDER BY s.step DESC LIMIT 1)
SELECT
  t.time_step_id,                                                               -- <run>-t<time>.
  calc_time_steps_name(t.time_step_id) AS name,                                 -- Display alias.
  t.run,                                                                        -- The run.
  t.time,                                                                       -- Time step t.
  t.previous_step,                                                              -- Time step t - 1; empty at t = 0.
  calc_time_steps_depth(t.time_step_id) AS depth,                               -- The run's horizon.
  calc_time_steps_width(t.time_step_id) AS width,                               -- Cells in the light cone at this time step.
  calc_time_steps_cell_count(t.time_step_id) AS cell_count,                     -- Cells computed at this time step; equals Width.
  calc_time_steps_black_count(t.time_step_id) AS black_count,                   -- Black cells on this line.
  calc_time_steps_line_density(t.time_step_id) AS line_density,                 -- Share of black on this line.
  calc_time_steps_center_value(t.time_step_id) AS center_value,                 -- c(t), the center term.
  calc_time_steps_cell_updates(t.time_step_id) AS cell_updates,                 -- Cells the rule computes to produce this line (none at t = 0).
  (SELECT settled #>> ARRAY[NULLIF(t.previous_step,''), 'cumulative_cell_updates'] FROM settled)::integer AS previous_cumulative_cell_updates,-- Updates through t - 1.
  (SELECT settled #>> ARRAY[t.time_step_id::text, 'cumulative_cell_updates'] FROM settled)::integer AS cumulative_cell_updates-- Cell updates needed to reach this line: (t + 1)^2 - 1.
FROM time_steps t;

-- ----------------------------------------------------------------------------
-- vw_columns: The cells at one position over time, read as a sequence in t. The center column (position 0) is the sequence of center-cell values all three problems are about.
-- Combines base table columns with calculated/lookup/aggregation fields.
-- ----------------------------------------------------------------------------
DROP VIEW IF EXISTS vw_columns CASCADE;
CREATE VIEW vw_columns WITH (security_invoker = ON) AS
SELECT
  t.column_id,                                                                  -- <run>-p<position>.
  calc_columns_name(t.column_id) AS name,                                       -- Display alias.
  t.run,                                                                        -- The run.
  t.position,                                                                   -- Position i.
  calc_columns_depth(t.column_id) AS depth,                                     -- The run's horizon.
  calc_columns_is_center(t.column_id) AS is_center,                             -- 1 for the center column.
  calc_columns_first_time(t.column_id) AS first_time,                           -- First time step at which the light cone reaches this column; earlier terms are background.
  calc_columns_cell_count(t.column_id) AS cell_count,                           -- Computed cells in this column.
  calc_columns_black_count(t.column_id) AS black_count,                         -- Black cells in this column.
  calc_columns_density(t.column_id) AS density                                  -- Share of black among terms 0 .. Depth (background terms count as white).
FROM columns t;

