  CASE WHEN r2.loop_id IS NULL THEN NULL ELSE COALESCE(NULLIF(calc_loops_name(r2.loop_id)::text, ''), r2.loop_id::text) END AS introduced_in_loop__fk_label
FROM predicates t
  LEFT JOIN terms r1 ON r1.term_id = t.root_term
  LEFT JOIN loops r2 ON r2.loop_id = t.introduced_in_loop
;

DROP VIEW IF EXISTS fk_labels_predicate_instances CASCADE;
CREATE VIEW fk_labels_predicate_instances WITH (security_invoker = ON) AS
SELECT
  t.predicate_instance_id AS __pk,
  CASE WHEN r1.predicate_id IS NULL THEN NULL ELSE COALESCE(NULLIF(calc_predicates_name(r1.predicate_id)::text, ''), r1.predicate_id::text) END AS predicate__fk_label,
  CASE WHEN r2.loop_id IS NULL THEN NULL ELSE COALESCE(NULLIF(calc_loops_name(r2.loop_id)::text, ''), r2.loop_id::text) END AS introduced_in_loop__fk_label,
  CASE WHEN r3.rule_table_entry_id IS NULL THEN NULL ELSE COALESCE(NULLIF(calc_rule_table_entries_name(r3.rule_table_entry_id)::text, ''), r3.rule_table_entry_id::text) END AS rule_table_entry__fk_label,
  CASE WHEN r4.run_id IS NULL THEN NULL ELSE COALESCE(NULLIF(calc_runs_name(r4.run_id)::text, ''), r4.run_id::text) END AS run__fk_label,
  CASE WHEN r5.period_test_id IS NULL THEN NULL ELSE COALESCE(NULLIF(calc_period_tests_name(r5.period_test_id)::text, ''), r5.period_test_id::text) END AS period_test__fk_label,
  CASE WHEN r6.periodicity_candidate_id IS NULL THEN NULL ELSE COALESCE(NULLIF(calc_periodicity_candidates_name(r6.periodicity_candidate_id)::text, ''), r6.periodicity_candidate_id::text) END AS periodicity_candidate__fk_label,
  CASE WHEN r7.mismatch_window_id IS NULL THEN NULL ELSE COALESCE(NULLIF(calc_mismatch_windows_name(r7.mismatch_window_id)::text, ''), r7.mismatch_window_id::text) END AS mismatch_window__fk_label,
  CASE WHEN r8.cell_id IS NULL THEN NULL ELSE COALESCE(NULLIF(calc_cells_name(r8.cell_id)::text, ''), r8.cell_id::text) END AS cell__fk_label,
  CASE WHEN r9.left_consistency_check_id IS NULL THEN NULL ELSE COALESCE(NULLIF(calc_left_consistency_checks_name(r9.left_consistency_check_id)::text, ''), r9.left_consistency_check_id::text) END AS left_consistency_check__fk_label,
  CASE WHEN r10.tail_candidate_id IS NULL THEN NULL ELSE COALESCE(NULLIF(calc_tail_candidates_name(r10.tail_candidate_id)::text, ''), r10.tail_candidate_id::text) END AS tail_candidate__fk_label,
  CASE WHEN r11.diagonal_period_test_id IS NULL THEN NULL ELSE COALESCE(NULLIF(calc_diagonal_period_tests_name(r11.diagonal_period_test_id)::text, ''), r11.diagonal_period_test_id::text) END AS diagonal_period_test__fk_label,
  CASE WHEN r12.diagonal_fact_id IS NULL THEN NULL ELSE COALESCE(NULLIF(calc_diagonal_facts_name(r12.diagonal_fact_id)::text, ''), r12.diagonal_fact_id::text) END AS diagonal_fact__fk_label,
  CASE WHEN r13.accelerator_claim_id IS NULL THEN NULL ELSE COALESCE(NULLIF(calc_accelerator_claims_name(r13.accelerator_claim_id)::text, ''), r13.accelerator_claim_id::text) END AS accelerator_claim__fk_label,
  CASE WHEN r14.tolerance_id IS NULL THEN NULL ELSE COALESCE(NULLIF(calc_tolerances_name(r14.tolerance_id)::text, ''), r14.tolerance_id::text) END AS tolerance__fk_label,
  CASE WHEN r15.algorithm_id IS NULL THEN NULL ELSE COALESCE(NULLIF(calc_algorithms_name(r15.algorithm_id)::text, ''), r15.algorithm_id::text) END AS algorithm__fk_label
FROM predicate_instances t
  LEFT JOIN predicates r1 ON r1.predicate_id = t.predicate
  LEFT JOIN loops r2 ON r2.loop_id = t.introduced_in_loop
  LEFT JOIN rule_table_entries r3 ON r3.rule_table_entry_id = t.rule_table_entry
  LEFT JOIN runs r4 ON r4.run_id = t.run
  LEFT JOIN period_tests r5 ON r5.period_test_id = t.period_test
  LEFT JOIN periodicity_candidates r6 ON r6.periodicity_candidate_id = t.periodicity_candidate
  LEFT JOIN mismatch_windows r7 ON r7.mismatch_window_id = t.mismatch_window
  LEFT JOIN cells r8 ON r8.cell_id = t.cell
  LEFT JOIN left_consistency_checks r9 ON r9.left_consistency_check_id = t.left_consistency_check
  LEFT JOIN tail_candidates r10 ON r10.tail_candidate_id = t.tail_candidate
  LEFT JOIN diagonal_period_tests r11 ON r11.diagonal_period_test_id = t.diagonal_period_test
  LEFT JOIN diagonal_facts r12 ON r12.diagonal_fact_id = t.diagonal_fact
  LEFT JOIN accelerator_claims r13 ON r13.accelerator_claim_id = t.accelerator_claim
  LEFT JOIN tolerances r14 ON r14.tolerance_id = t.tolerance
  LEFT JOIN algorithms r15 ON r15.algorithm_id = t.algorithm
;

